from pathlib import Path
import json
p=Path('/tmp/claim-audit-ujro7ytd')
s=json.loads((p/'input/source-ledger.json').read_text())
c=json.loads((p/'claims.json').read_text())
lookup={a:(path,t) for path,anchors in s.items() for a,t in anchors.items()}
def ev(*anchors):
 return [{'path':lookup[a][0],'anchor':a,'quote':lookup[a][1]} for a in anchors]
def proof(name,target,relation):
 return [{'module':'Audit','theorem':'Audit.'+name,'relation':relation,'target':target}]
common=['The accepted register and supplied fictional rules are faithful inputs; the audit does not authenticate their historical accuracy.', 'Gregorian UTC dates use receipt day zero and inclusive 17:00 deadlines; no working-day rollover is permitted.']
findings=[]
def add(id,q,anchors,rules,steps,state,arg,formal,name,target,rec,limits=None):
 item=next(x for x in c if x['claim_id']==id)
 f={k:item[k] for k in ['claim_id','report_quote','report_anchor']}
 f.update(parent_claim=item['parent_claim'],atomic_target=item['atomic_target'],question=q,evidence=ev(*anchors),rules=rules,assumptions=common,reasoning=[f'{i+1}. {v}' for i,v in enumerate(steps)],semantic_state=state,argument_status=arg,formal_status=formal,proofs=proof(name,target,{'proved':'supports','refuted':'refutes','auxiliary':'auxiliary'}[formal]) if name else [],limits=limits or ['The conclusion is conditional on accurate supplied records and the stated W-6 scope; it does not certify source authenticity or apply outside these four cases.'],recommendation=rec)
 findings.append(f)
R=['V1-01 and V2-01 choose revision by accepted receipt before versus at/after 2028-03-01 00:00 UTC; assignment and export date are immaterial.']
D=['V1-02 grants standard revision-1 cases 10 calendar days; V2-02 grants standard revision-2 cases 7 calendar days, receipt date day zero, at 17:00 UTC inclusive.']
add('VD-01a','Does revision 1 govern D-201 under the receipt-based transition at the evidence cutoff?', ['C01','V1-01','V2-01','T01'],R,['C01 records accepted receipt on February 20, before the March 1 boundary.', 'The later assignment and dashboard revision-2 label cannot replace accepted receipt.', 'Revision 1 applies; the model checks the finite receipt-based selector.'],'supported','sufficient','proved','version201','Audit.revision Audit.c201 = 1','Retain the version statement and cite C01 plus the transition clause.')
add('VD-01b','Is D-201 standard-case deadline March 1, 2028 at 17:00 UTC?', ['C01','V1-01','V1-02','V2-01'],R+D,['D-201 is standard and received February 20 under revision 1.', 'February 20 is offset 0; leap-day February 29 is offset 9; March 1 is offset 10.', 'Adding ten dates gives March 1 at 17:00, minute 15420 from origin. Python Gregorian date offsets independently agree with manual counting.'],'supported','sufficient','proved','deadline201','Audit.standardDue Audit.c201 = some (Audit.at17 10)','Retain the stated deadline and show the leap-year calculation.')
add('VD-02','Was D-201 submission at the exact inclusive deadline timely?', ['C01','V1-01','V1-02'],R+D,['D-201 deadline is March 1 17:00, from February 20 plus ten dates.', 'C01 submission is March 1 17:00, exactly equal to the deadline.', 'Inclusive means submission ≤ deadline; equality is timely.'],'supported','sufficient','proved','timely201','Audit.standardDue Audit.c201 = some (Audit.at17 10) ∧ Audit.timely Audit.c201.submission (Audit.at17 10)','Retain the finding and explain the inclusive boundary.')
add('VD-03','Does D-202 receive revision 2 because assignment followed the effective instant?', ['C02','V1-01','V2-01','T01'],R,['C02 accepted receipt is February 29 23:59, minute 14399; March 1 00:00 is minute 14400.', 'Receipt is one minute before the boundary, so revision 1 is retained.', 'The assignment-based inference uses the wrong event. T01 independently explains why its revision-2 dashboard label is not a competing applicability rule.', 'The model establishes revision 1 and explicitly denies revision 2 for this in-scope case.'],'refuted','invalid_inference','refuted','version202Refuted','Audit.revision Audit.c202 ≠ 2 ∧ Audit.revision Audit.c202 = 1','Replace revision 2 with revision 1 and select the version from accepted receipt.')
add('VD-04','Is D-202 deadline March 10 17:00 despite its report misclassifying the revision?', ['C02','V1-01','V1-02','V2-01'],R+D,['D-202 is standard and its February 29 accepted receipt selects revision 1.', 'February 29 is offset 9. Adding ten calendar dates gives offset 19, March 10.', 'The deadline is March 10 17:00, minute 28380. This exact deadline is independently supported even though VD-03 provides an incompatible version premise.'], 'supported','sufficient','proved','deadline202','Audit.standardDue Audit.c202 = some (Audit.at17 19)','Retain the date, but explain that revision 1 and its ten-day rule establish it; repair VD-03.', ['Independent source reconstruction supports the date. The surrounding report contains a version error; support for this date does not validate that explanation.'])
add('VD-05','Was D-202 submission at March 10 17:01 within its inclusive 17:00 deadline?', ['C02','V1-01','V1-02'],R+D,['The correct revision-1 deadline is March 10 at 17:00, minute 28380.', 'The recorded submission is March 10 17:01, minute 28381.', '28381 exceeds 28380; inclusive 17:00 does not admit 17:01. D-202 is the direct in-scope counterexample to its timeliness assertion.'],'refuted','invalid_inference','refuted','timely202Refuted','Audit.standardDue Audit.c202 = some (Audit.at17 19) ∧ ¬ Audit.timely Audit.c202.submission (Audit.at17 19)','Replace timely with late by one minute.')
add('VD-06a','Does accepted receipt at the exact transition instant put D-203 under revision 2?', ['C03','V2-01'],R,['C03 accepted receipt is exactly March 1 00:00, minute 14400.', 'The explicit at-or-after transition includes the boundary instant.', 'Revision 2 governs D-203, independently of assignment.'],'supported','sufficient','proved','version203','Audit.revision Audit.c203 = 2','Retain the version statement and cite the inclusive transition clause.')
add('VD-06b','Was standard D-203 submission at March 8 17:00 timely under revision 2?', ['C03','V2-01','V2-02'],R+D,['D-203 is standard and received at the revision-2 boundary.', 'March 1 is offset 10. Receipt day zero plus seven dates is offset 17, March 8.', 'Its March 8 17:00 submission equals the inclusive deadline, so it is timely.'],'supported','sufficient','proved','timely203','Audit.standardDue Audit.c203 = some (Audit.at17 17) ∧ Audit.timely Audit.c203.submission (Audit.at17 17)','Retain the timely finding; cite the seven-day rule and receipt-day-zero convention.')
add('VD-07','Can receipt-day-one counting justify March 7 17:00 as D-203 deadline?', ['C03','V2-01','V2-02'],R+D,['V2-02 explicitly makes receipt date day zero; the report instead counts it as day one.', 'Seven dates after March 1 is March 8 (offset 17), not March 7 (offset 16).', 'The model checks the actual deadline and its inequality with the claimed March 7 deadline, so this is a direct refutation, not merely missing support.'],'refuted','invalid_inference','refuted','deadline203Refuted','Audit.standardDue Audit.c203 ≠ some (Audit.at17 16) ∧ Audit.standardDue Audit.c203 = some (Audit.at17 17)','Correct the deadline to March 8 17:00 and count receipt as day zero.')
restricted=['V1-03 and V2-03 reserve restricted-case deadlines and pause criteria exclusively to Annex R; standard deadlines cannot be substituted.', 'The supplied file inventory is not completeness evidence for Annex R rules or pause decisions.']
aux='Audit.standardDue Audit.c204 = none ∧ ∃ early late : Nat, early = Audit.at17 18 ∧ late ≠ Audit.at17 18 ∧ ¬ Audit.timely Audit.c204.submission early ∧ Audit.timely Audit.c204.submission late'
lims=['Annex R is absent. The model cannot determine the actual restricted deadline, pause criteria, or whether a pause was approved.', 'The existential theorem compares hypothetical completions of missing Annex R data. It is auxiliary non-entailment evidence, not proof that either hypothetical deadline is legally operative or that the report assertion is false.']
add('VD-08','Does supplied evidence determine D-204 final deadline as March 9 17:00?', ['C04','V1-03','V2-01','V2-03','T02'],restricted,['D-204 is restricted; its March 2 receipt places it under revision 2, but V2-03 excludes the seven-day standard rule.', 'March 9 would result from borrowing the standard seven-day formula. That borrowing is unauthorized; no report citation or independent supplied source gives a restricted duration.', 'C04 establishes a filed pause request only, while T02 supplies neither Annex R nor an independent final deadline.', 'Hypothetical Annex R deadlines March 9 17:00 and March 13 17:00 both leave the recorded receipt and submission unchanged and contradict no supplied restricted duration. Their differing dates demonstrate unresolved precision.'], 'undetermined','insufficient_support','auxiliary','restrictedDeadlineOpen',aux,'Obtain Annex R applicable to D-204 and relevant pause decisions before publishing a final deadline.',lims)
add('VD-09','Does D-204 recorded March 12 16:00 submission establish timeliness with no Annex R deadline?', ['C04','V1-03','V2-03','T02'],restricted,['C04 fixes the submission at March 12 16:00 but supplies no final restricted deadline.', 'A pause request is established; approval and its effect are not. Absence of a supplied approval decision cannot be converted into proof that approval never occurred.', 'Independent review of all supplied rules and T02 finds no duration, calendar basis, pause criteria or final due date.', 'With hypothetical March 9 17:00 deadline, the recorded submission is late; with hypothetical March 13 17:00 deadline, it is timely. The auxiliary model holds all observed case data constant and demonstrates why present information determines neither outcome.'], 'undetermined','insufficient_support','auxiliary','restrictedDeadlineOpen',aux,'Obtain the applicable Annex R and evidence of any deadline adjustments; then compare the exact submission timestamp to the final deadline.',lims)
add('VD-10','Is revision 2 objectively fairer for applicants under any supplied evaluable criterion?', ['V1-02','V2-02','T03'],['A substantive fairness comparison requires an operational criterion, affected population and relevant outcomes; no such criterion is supplied.'],['The standard duration changes from ten days to seven; this numerical change alone does not define fairness.', 'T03 attributes the word fairer to an informal service-team comment. Attribution establishes that the comment was made, not the underlying value judgment.', 'No measurable criterion or comparison population supports a formal truth test for the exact claim.'], 'not_applicable','nonformal','not_attempted',None,None,'Attribute the opinion to the service team or specify a fairness criterion and evidence before presenting a comparative finding.', ['No Lean target is proposed for the undefined fairness judgment. This does not refute the opinion or settle whether applicants prefer one timetable.'])
(p/'findings.json').write_text(json.dumps(findings,indent=2)+'\n')
for item in c: item['coverage']='audited'; item['finding_id']=item['claim_id']
(p/'claims.json').write_text(json.dumps(c,indent=2)+'\n')
print(f'Wrote {len(findings)} findings.')
